import {documentDescriptor,routeKey} from './document-registry.mjs';
import {defaultGrid} from '../../authoring/editor/kernel.mjs';
const capabilities=Object.freeze({move:false,resize:false,layer:false,edit:false,remove:false});
// Aggregate identity only: application/catalogue internals never become authoring fields.
export function protectedDocument(route,definition,title){const id='protected:'+routeKey(route),sid=id+':section:application',bid=sid+':aggregate',block={id:bid,type:definition.source==='application'?'application':'dynamic',version:1,content:{binding:bid,source:definition.source},presentation:{},capabilities},layouts=Object.fromEntries(['desktop','mobile'].map(bp=>[bp,{grid:{...defaultGrid(),columns:bp==='mobile'?8:24},rows:16,placements:{[bid]:{source:'manual',value:{col:0,row:0,cols:bp==='mobile'?8:24,rows:16,z:0,visible:true,locked:true}}}}]));const record={id,manifest:{schemaVersion:1,id,sections:[{id:sid,policy:'layer',order:[bid],blocks:{[bid]:block},layouts}]}};return documentDescriptor({route,type:definition.type,title,record,editable:false,protectedRegions:[definition.source]});}
export function protectedFeedback(descriptor){if(descriptor.type==='product')return 'Product presentation preview · product title, media, price, stock, variants and purchase controls remain catalogue-authoritative and read only.';if(descriptor.type==='application')return 'Protected application preview · tool internals, equations and actions are not editable website blocks.';if(descriptor.type==='category')return 'Dynamic category preview · products, pricing and stock remain catalogue-authoritative.';if(descriptor.type==='dynamic')return 'Dynamic content preview · read only here; News publication remains in its specialist workspace.';return 'Website preview · this page is read only. Interactive tools and commerce actions are disabled.';}
